// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(amount > 0);
        // fund c with exactly 1 wei, so any amount > 1 makes the transfer impossible
        vm.deal(address(c), 1);
        vm.assume(amount > address(c).balance);

        // adversarial receiver that rejects Ether
        Reverter receiver = new Reverter();

        vm.prank(actor);
        bool ok;
        try c.sendTo(address(receiver), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: with insufficient contract balance and a rejecting receiver,
        // sendTo must NOT report success. P reverts (ok == false);
        // M's unchecked send silently fails so ok == true.
        assertTrue(!ok, "sendTo must revert when it cannot transfer the amount");
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
